function a(){return{pageSize:10,size:"small",showTotal:t=>`共 ${t} 条`}}function i(t){if(!t&&t!==0)return"-";if(t===0)return"0 B";const n=["B","KB","MB","GB","TB"],r=Math.min(Math.floor(Math.log2(t)/10),n.length-1);return`${(t/1024**r).toFixed(r===0?0:1)} ${n[r]}`}function o(t){if(!t)return"-";const n=new Date(t);return Number.isNaN(n.getTime())?t:n.toLocaleString("zh-CN",{hour12:!1})}function e(t){try{return JSON.stringify(t,null,2)}catch{return String(t)}}export{i as a,e as b,o as f,a as u};
